#!/usr/bin/env bash
# Usage: apply.sh <dim_min> <dim_percent> <lock_min> <dpms_min> <suspend_min>
# Regenerates ~/.config/hypr/hypridle.conf (0 minutes = step disabled) and restarts hypridle.
dim=${1:-0}; dimpct=${2:-10}; lock=${3:-0}; dpms=${4:-0}; susp=${5:-0}
conf="${XDG_CONFIG_HOME:-$HOME/.config}/hypr/hypridle.conf"

{
cat <<'H'
# Generated by the Settings app (Super+I > General > Idle). Edit values there.
$lock_cmd = hyprctl dispatch 'hl.dsp.global("quickshell:lock")' & pidof qs quickshell hyprlock || hyprlock
$suspend_cmd = systemctl suspend || loginctl suspend

general {
    lock_cmd = $lock_cmd
    before_sleep_cmd = loginctl lock-session
    after_sleep_cmd = hyprctl dispatch 'hl.dsp.global("quickshell:lockFocus")'
    inhibit_sleep = 3
}
H
if [ "$dim" -gt 0 ]; then cat <<H

listener {
    timeout = $((dim * 60))
    on-timeout = brightnessctl -s set ${dimpct}%
    on-resume = brightnessctl -r
}
H
fi
if [ "$lock" -gt 0 ]; then cat <<H

listener {
    timeout = $((lock * 60))
    on-timeout = loginctl lock-session
}
H
fi
if [ "$dpms" -gt 0 ]; then cat <<H

listener {
    timeout = $((dpms * 60))
    on-timeout = hyprctl dispatch 'hl.dsp.dpms({ action = "disable" })'
    on-resume = hyprctl dispatch 'hl.dsp.dpms({ action = "enable" })'
}
H
fi
if [ "$susp" -gt 0 ]; then cat <<H

listener {
    timeout = $((susp * 60))
    on-timeout = \$suspend_cmd
}
H
fi
} > "$conf.tmp"
# Nothing changed (e.g. settings page just opened): leave hypridle alone
if cmp -s "$conf.tmp" "$conf"; then rm -f "$conf.tmp"; exit 0; fi
mv "$conf.tmp" "$conf"

pkill -x hypridle
nohup hypridle >/dev/null 2>&1 &
